package za.co.handyflow.platform.fleet.application.storage;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where Fleet keeps uploaded file bytes. A port on purpose: the metadata lives in the
 * database, the bytes live behind this interface, so swapping local disk for S3 / your
 * existing evidence store means writing one adapter, not touching Fleet's services.
 * <p>
 * Keys are generated by Fleet (never derived from user input) and look like
 * {@code fleet/<tenantId>/<vehicleId>/<uuid>}.
 */
public interface FleetFileStorage {

    void store(String key, InputStream content, long sizeBytes, String contentType) throws IOException;

    /** Caller must close the stream. */
    InputStream open(String key) throws IOException;

    /** Best-effort; used to clean up after a failed transaction. Must not throw if the key is absent. */
    void delete(String key) throws IOException;
}